'use client'

import { toggleNotificationPreference } from '@/app/actions'

interface NotificationToggleProps {
  userId: string
  notificationsEnabled: boolean
}

export function NotificationToggle({ userId, notificationsEnabled }: NotificationToggleProps) {
  return (
    <form action={toggleNotificationPreference.bind(null, userId, notificationsEnabled)}>
      <button type="submit">
        Notifications: {notificationsEnabled ? 'ON' : 'OFF'}
      </button>
    </form>
  )
}

