'use server'

import { revalidatePath } from 'next/cache'

export async function toggleNotificationPreference(userId: string, currentPreference: boolean): Promise<void> {
  'use server'

  await db.user.update({
    where: { id: userId },
    data: { notificationsEnabled: !currentPreference }
  })

  revalidatePath('/', 'page')
}

